svg.script:
(function () {
  const svg = document.documentElement;
  const tip = document.getElementById('hover-tooltip');
  const box = tip.querySelector('rect');
  const text = tip.querySelector('text');
  const canvasWidth = Number(svg.getAttribute('width'));
  const canvasHeight = Number(svg.getAttribute('height'));
  for (const path of svg.querySelectorAll('path')) {
    const label = path.getAttribute('data-tip') || path.parentElement.getAttribute('data-tip');
    if (!label) continue;
    path.addEventListener('mousemove', event => {
      text.textContent = label;
      tip.setAttribute('visibility', 'visible');
      const width = Math.ceil(text.getComputedTextLength()) + 18;
      box.setAttribute('width', width);
      const point = svg.createSVGPoint();
      point.x = event.clientX;
      point.y = event.clientY;
      const local = point.matrixTransform(svg.getScreenCTM().inverse());
      const x = Math.max(5, Math.min(local.x + 12, canvasWidth - width - 5));
      const y = local.y > 42 ? local.y - 38 : Math.min(local.y + 12, canvasHeight - 35);
      tip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    });
    path.addEventListener('mouseleave', () => tip.setAttribute('visibility', 'hidden'));
  }
})();
